-- NOT YET APPLIED (28 Nov 2026). Sent in chat as RUN_THIS_4_school_logos_photos.sql.
-- School media for the schools added 27 and 28 Nov 2026 (logo, banner photo, description) from Wikipedia and
-- Wikimedia Commons, free licences only, from the owner's fetch_school_media.py runs. Only fills empty fields; never overwrites.
-- Left out (wrong page matched): Curtis Institute of Music, Eikei University of Hiroshima, Ghent University Global Campus, Hosei University, Minerva University, The Juilliard School, University of Hyogo, Washington University in St Louis.
-- Logo only (page was the parent university, so its photo and description would show the wrong campus): George Mason University Korea, Northeastern University Oakland, SUNY Korea (Stony Brook University), The University of Utah Asia Campus.
-- Harbin Institute of Technology: the "logo" was a campus photo, so only the photo and description are used.
begin;
update public.schools s set
  logo_url = coalesce(nullif(s.logo_url,''), v.logo_url),
  logo_credit = case when coalesce(s.logo_url,'')='' then v.logo_credit else s.logo_credit end,
  image_url = coalesce(nullif(s.image_url,''), v.image_url),
  image_credit = case when coalesce(s.image_url,'')='' then v.image_credit else s.image_credit end,
  description = coalesce(nullif(s.description,''), v.description),
  description_credit = case when coalesce(s.description,'')='' then v.description_credit else s.description_credit end
from (values
('3466114a-d132-4229-9356-363bd90784d0'::uuid,$q$https://thumb.wikimedia.org/wikipedia/commons/thumb/d/d6/University_of_Tokyo_logo_%282024%29.svg/500px-University_of_Tokyo_logo_%282024%29.svg.png?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail$q$,$q$Photo: 東京大学, Public domain, Wikimedia Commons$q$,$q$https://thumb.wikimedia.org/wikipedia/commons/thumb/2/23/Yasuda_Auditorium_-_Tokyo_University_3.jpg/1280px-Yasuda_Auditorium_-_Tokyo_University_3.jpg?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail$q$,$q$Photo: Kakidai, CC BY-SA 4.0, Wikimedia Commons$q$,$q$The University of Tokyo (UTokyo) is a public research university in Bunkyō, Tokyo, Japan. Founded in 1877 as the nation's first modern university by the merger of several pre-westernisation era institutions, its direct precursors include the Tenmongata, founded in 1684, and the Shōheizaka Institute. The university consists of 10 faculties, 15 graduate schools, and 11 affiliated research institutes.$q$,$q$Description: Wikipedia, CC BY-SA 4.0$q$),
('15b5403c-2619-4e04-bcff-9dfb8fea255a'::uuid,$q$https://thumb.wikimedia.org/wikipedia/commons/thumb/a/a5/Kyoto_University_emblem.svg/500px-Kyoto_University_emblem.svg.png?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail$q$,$q$Photo: 京都大学、小川録郎、川崎清、久谷政樹, Public domain, Wikimedia Commons$q$,$q$https://thumb.wikimedia.org/wikipedia/commons/thumb/0/05/Kyoto_University_Clock_Tower.jpg/1280px-Kyoto_University_Clock_Tower.jpg?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail$q$,$q$Photo: Soraie8288, CC BY-SA 4.0, Wikimedia Commons$q$,$q$Kyoto University, or KyotoU, is a national research university in Kyoto, Japan. Founded in 1897, it is one of the former Imperial Universities and the second oldest university in Japan. The university has ten undergraduate faculties, eighteen graduate schools, and thirteen research institutes.$q$,$q$Description: Wikipedia, CC BY-SA 4.0$q$),
('90f61193-059b-450c-ad95-928c8a2a7992'::uuid,null,null,$q$https://thumb.wikimedia.org/wikipedia/commons/thumb/7/7d/Kawauchi_campus_of_Tohoku_University_20220910a.jpg/1280px-Kawauchi_campus_of_Tohoku_University_20220910a.jpg?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail$q$,$q$Photo: 掬茶, CC BY-SA 4.0, Wikimedia Commons$q$,$q$Tohoku University is a public research university in Sendai, Miyagi, Japan. It is colloquially referred to as Tohokudai or Tonpei. Established in 1907 as the third of the Imperial Universities, after the University of Tokyo and Kyoto University, it initially focused on science and medicine, later expanding to include humanities studies as well.$q$,$q$Description: Wikipedia, CC BY-SA 4.0$q$),
('8ad94efe-6c8a-42bf-a2a0-c4af0e1cbb3e'::uuid,$q$https://thumb.wikimedia.org/wikipedia/commons/thumb/4/41/University_of_Osaka_logo%2C_A.svg/500px-University_of_Osaka_logo%2C_A.svg.png?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail$q$,$q$Photo: 大阪大学企画部広報課大阪大学広報・ブランド戦略本部, CC BY-SA 3.0, Wikimedia Commons$q$,$q$https://thumb.wikimedia.org/wikipedia/commons/thumb/0/0f/Osaka_University_Faculty_of_Medicine.jpg/1280px-Osaka_University_Faculty_of_Medicine.jpg?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail$q$,$q$Photo: ignis, CC BY-SA 3.0, Wikimedia Commons$q$,$q$The University of Osaka, abbreviated as UOsaka or Handai, is a national research university in Osaka Prefecture, Japan. The university traces its roots back to Edo-era institutions Tekijuku and Kaitokudo, and was officially established in 1931 as the sixth of the Imperial Universities in Japan with two faculties: science and medicine. Following the post-war educational reform, it merged with three pre-war higher schools, reconstructed into a national reseaerch university with five faculties: science, medicine, letters, law and economics, and engineering.$q$,$q$Description: Wikipedia, CC BY-SA 4.0$q$),
('cbc5a059-3e9c-46b7-8a3e-1a40fb86d85f'::uuid,$q$https://thumb.wikimedia.org/wikipedia/commons/thumb/9/9a/%E6%9D%B1%E4%BA%AC%E7%A7%91%E5%AD%A6%E5%A4%A7%E5%AD%A62024.jpg/500px-%E6%9D%B1%E4%BA%AC%E7%A7%91%E5%AD%A6%E5%A4%A7%E5%AD%A62024.jpg?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail$q$,$q$Photo: Unknown authorUnknown author, Public domain, Wikimedia Commons$q$,$q$https://thumb.wikimedia.org/wikipedia/commons/thumb/2/29/Main_Building_-_Tokyo_Institute_of_Technology.jpg/1280px-Main_Building_-_Tokyo_Institute_of_Technology.jpg?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail$q$,$q$Photo: Kakidai, CC BY-SA 4.0, Wikimedia Commons$q$,$q$The Institute of Science Tokyo is a public research university in Tokyo, Japan. It was officially established on 1 October 2024, by a merger between the Tokyo Institute of Technology and Tokyo Medical and Dental University. The main campus is located in Ookayama, Meguro, with satellite campuses in Yokohama, Minato-ku, Bunkyo-ku, and Ichikawa.$q$,$q$Description: Wikipedia, CC BY-SA 4.0$q$),
('e929f2ad-aa18-40dd-baef-f645285b3920'::uuid,$q$https://thumb.wikimedia.org/wikipedia/commons/thumb/4/41/Nagoya_University_logo%2C_type_1.svg/500px-Nagoya_University_logo%2C_type_1.svg.png?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail$q$,$q$Photo: 名古屋大学, Public domain, Wikimedia Commons$q$,$q$https://thumb.wikimedia.org/wikipedia/commons/thumb/0/01/Nagoya_University_dk4591.jpg/1280px-Nagoya_University_dk4591.jpg?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail$q$,$q$Photo: DrKssn, CC BY-SA 3.0, Wikimedia Commons$q$,$q$Nagoya University, abbreviated to Meidai or NU, is a Japanese national research university located in Chikusa-ku, Nagoya. It was established in 1939 as the last of the nine Imperial Universities in the then Empire of Japan, and is now a Designated National University. The university is the birthplace of the Sakata School of physics and the Hirata School of chemistry.$q$,$q$Description: Wikipedia, CC BY-SA 4.0$q$),
('dc182298-147e-458e-9cf4-7f10747696e8'::uuid,$q$https://thumb.wikimedia.org/wikipedia/commons/thumb/4/4f/Kyushu_University_logo%2C_type_D.svg/500px-Kyushu_University_logo%2C_type_D.svg.png?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail$q$,$q$Photo: 九州大学広報室, Public domain, Wikimedia Commons$q$,$q$https://thumb.wikimedia.org/wikipedia/commons/thumb/d/d2/Kyushu_University_Ito_Campus_Center_Zone_and_East_Zone_20180808.jpg/1280px-Kyushu_University_Ito_Campus_Center_Zone_and_East_Zone_20180808.jpg?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail$q$,$q$Photo: 新幹線, CC BY-SA 4.0, Wikimedia Commons$q$,$q$Kyushu University, abbreviated to Kyudai, is a public research university located in Fukuoka, Japan, on the island of Kyushu. Founded in 1911 as the fourth Imperial University in Japan, it has been recognised as a leading institution of higher education and research in Kyushu, Japan, and beyond. The history of the university began a few decades before its founding when the medical school of the Fukuoka Domain was established in 1867, the final year of the Edo period.$q$,$q$Description: Wikipedia, CC BY-SA 4.0$q$),
('71ed5566-9d56-4126-a840-c0f5ad80021d'::uuid,$q$https://thumb.wikimedia.org/wikipedia/commons/thumb/7/76/Hokkaido_University_logo%2C_2.svg/500px-Hokkaido_University_logo%2C_2.svg.png?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail$q$,$q$Photo: 北海道大学, Public domain, Wikimedia Commons$q$,$q$https://upload.wikimedia.org/wikipedia/commons/6/60/HokkaidoDaigakuSapporoKyanpasuSeimon2005-2.jpg?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail_unscaled$q$,$q$Public domain, Wikimedia Commons$q$,$q$Hokkaido University, or Hokudai, is a public research university in Sapporo, Hokkaido, Japan. Founded in 1918, it is the fifth-oldest government-authorised university in Japan and one of the former Imperial Universities. The university finds its roots in Sapporo Agricultural College, which was a pioneer in the country's modern agricultural education and research, founded in 1876.$q$,$q$Description: Wikipedia, CC BY-SA 4.0$q$),
('5c988691-35cd-4052-b611-c2e7727f132c'::uuid,$q$https://thumb.wikimedia.org/wikipedia/commons/thumb/d/dd/Logo_of_University_of_Tsukuba.svg/500px-Logo_of_University_of_Tsukuba.svg.png?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail$q$,$q$Photo: 筑波大学, Public domain, Wikimedia Commons$q$,$q$https://thumb.wikimedia.org/wikipedia/commons/thumb/3/33/5C_building.JPG/1280px-5C_building.JPG?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail$q$,$q$Photo: On-chan, CC BY-SA 3.0, Wikimedia Commons$q$,$q$The University of Tsukuba is a national research university in Tsukuba, Ibaraki Prefecture, Japan. Chartered in October 1973 as Japan's first "new concept university" with the Tokyo University of Education as its parent institution, it traces its origins to the first normal school in Japan, established in Tokyo in 1872, which gives it one of the oldest institutional lineages of any Japanese university. It is one of the pre-war government-established universities and, together with Hiroshima University, one of the two successors of the former "universities of literature and science".$q$,$q$Description: Wikipedia, CC BY-SA 4.0$q$),
('a4c21396-ed56-4b43-8a85-dcf4ca7936a9'::uuid,$q$https://upload.wikimedia.org/wikipedia/commons/d/dc/HUlogo.jpg?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail_unscaled$q$,$q$Photo: HU, Public domain, Wikimedia Commons$q$,$q$https://thumb.wikimedia.org/wikipedia/commons/thumb/b/bf/Faculty_of_Science%2C_Hiroshima_University_-_Feb_1%2C_2005.jpg/1280px-Faculty_of_Science%2C_Hiroshima_University_-_Feb_1%2C_2005.jpg?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail$q$,$q$Photo: hu album, CC BY 2.0, Wikimedia Commons$q$,$q$Hiroshima University is a Japanese national research university located in Higashihiroshima and Hiroshima, Japan. Established in 1929, it was chartered as a university in 1949 following the merge of a number of national educational institutions. Its abbreviated form is Hirodai, and it is included in the group of quasi-elite national universities in Japan known as “Kaneokachihiro”.$q$,$q$Description: Wikipedia, CC BY-SA 4.0$q$),
('88cab75f-9c91-46b2-928c-8947a0cf2648'::uuid,$q$https://thumb.wikimedia.org/wikipedia/commons/thumb/d/d8/Waseda_university_logo.svg/500px-Waseda_university_logo.svg.png?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail$q$,$q$Photo: 早稲田大学, Public domain, Wikimedia Commons$q$,$q$https://thumb.wikimedia.org/wikipedia/commons/thumb/2/2b/Okuma_Auditorium.jpg/1280px-Okuma_Auditorium.jpg?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail$q$,$q$Photo: Wiiii, CC BY-SA 3.0, Wikimedia Commons$q$,$q$Waseda University, abbreviated as Waseda or Sōdai, is a private research university in Shinjuku, Tokyo. Founded in 1882 as the Tōkyō Professional School by Ōkuma Shigenobu, the eighth and eleventh prime minister of Japan, the school was formally renamed Waseda University in 1902. Waseda is organized into 36 departments: 13 undergraduate schools and 23 graduate schools.$q$,$q$Description: Wikipedia, CC BY-SA 4.0$q$),
('9128b332-5e9b-4b30-873f-c36c65094197'::uuid,$q$https://thumb.wikimedia.org/wikipedia/commons/thumb/7/7d/Keio_University_logo%2C_ja_and_en_3.svg/500px-Keio_University_logo%2C_ja_and_en_3.svg.png?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail$q$,$q$Photo: 慶応義塾大学, Public domain, Wikimedia Commons$q$,$q$https://thumb.wikimedia.org/wikipedia/commons/thumb/7/79/Old_Keio_University_Library_3.jpg/1280px-Old_Keio_University_Library_3.jpg?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail$q$,$q$Photo: Kakidai, CC BY-SA 4.0, Wikimedia Commons$q$,$q$Keio University, abbreviated as Keio or Keidai, is a private research university located in Minato, Tokyo, Japan. It was originally established as a school for Western studies in 1858 in Edo. It was granted university status in 1920, becoming one of the first private universities in the country.$q$,$q$Description: Wikipedia, CC BY-SA 4.0$q$),
('246ee828-69a2-4fb8-a388-d7b79c63334a'::uuid,null,null,$q$https://thumb.wikimedia.org/wikipedia/commons/thumb/e/ef/%E6%9D%B1%E4%BA%AC%E5%A4%96%E5%9B%BD%E8%AA%9E%E5%A4%A7%E5%AD%A6_-_panoramio_%2816%29.jpg/1280px-%E6%9D%B1%E4%BA%AC%E5%A4%96%E5%9B%BD%E8%AA%9E%E5%A4%A7%E5%AD%A6_-_panoramio_%2816%29.jpg?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail$q$,$q$Photo: kanesue, CC BY 3.0, Wikimedia Commons$q$,$q$Tokyo University of Foreign Studies, often referred to as TUFS, is a specialist national research university in Fuchū, Tokyo, Japan. TUFS is primarily devoted to foreign language, international affairs and area studies.$q$,$q$Description: Wikipedia, CC BY-SA 4.0$q$),
('8ec55b14-d23f-47af-a923-f9337b132d40'::uuid,null,null,$q$https://thumb.wikimedia.org/wikipedia/commons/thumb/e/e8/University_of_Aizu_in_bloom.jpg/1280px-University_of_Aizu_in_bloom.jpg?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail$q$,$q$Photo: Terakin, CC BY-SA 3.0, Wikimedia Commons$q$,$q$The University of Aizu is a public university in Aizuwakamatsu, Fukushima Prefecture, Japan. The university is dedicated to computer science and engineering and English language education.$q$,$q$Description: Wikipedia, CC BY-SA 4.0$q$),
('5e0d3927-18eb-4715-8c77-70626a337ef6'::uuid,$q$https://thumb.wikimedia.org/wikipedia/commons/thumb/a/a2/Akita_International_University_Logo.svg/500px-Akita_International_University_Logo.svg.png?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail$q$,$q$Photo: 公立大学法人国際教養大学, Public domain, Wikimedia Commons$q$,$q$https://thumb.wikimedia.org/wikipedia/commons/thumb/f/fa/Akita_International_University_20190602.jpg/1280px-Akita_International_University_20190602.jpg?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail$q$,$q$Photo: 掬茶, CC BY-SA 4.0, Wikimedia Commons$q$,$q$Akita International University, or AIU, is a public university located in Akita City, Akita Prefecture, Japan. Established in 2004 and modeled on American liberal arts colleges, AIU is one of the few universities in Japan offering all of its courses in English. It has currently 211 international partner institutions in 52 different countries and regions.$q$,$q$Description: Wikipedia, CC BY-SA 4.0$q$),
('acedd4a6-38e8-4ff3-aa23-f3862570edc6'::uuid,null,null,$q$https://thumb.wikimedia.org/wikipedia/commons/thumb/d/d3/Sophia_University_Yotsuya_Campus4.jpg/1280px-Sophia_University_Yotsuya_Campus4.jpg?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail$q$,$q$Photo: Keiichi Yasu, CC BY-SA 2.0, Wikimedia Commons$q$,$q$Sophia University is a private Jesuit research university in Tokyo, Japan. Founded in 1913 by the Jesuits, it was granted university status in 1928, becoming the first Catholic university in Japan. Sophia University has 12,080 undergraduate students and 1,357 postgraduate students.$q$,$q$Description: Wikipedia, CC BY-SA 4.0$q$),
('031f4064-43a6-4ec9-9171-4629d6e580c1'::uuid,$q$https://thumb.wikimedia.org/wikipedia/commons/thumb/1/17/Doshisha_University_logo.svg/500px-Doshisha_University_logo.svg.png?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail$q$,$q$Photo: 同志社大学, Public domain, Wikimedia Commons$q$,$q$https://thumb.wikimedia.org/wikipedia/commons/thumb/d/d8/Mukoku-kan_%28Kyotanabe_Campus%2C_Doshisha_University%29.JPG/1280px-Mukoku-kan_%28Kyotanabe_Campus%2C_Doshisha_University%29.JPG?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail$q$,$q$Photo: RoyHalzenski, Public domain, Wikimedia Commons$q$,$q$Doshisha University, also referred to as Dodai, is a private university in Kyoto, Japan. Established in 1875, it is one of Japan's oldest private institutions of higher learning, and has approximately 30,000 students enrolled on four campuses in Kyoto. It is one of Japan's "Global 30" universities and a member of "Kan-Kan-Dō-Ritsu", a group of four leading private universities in western Japan's Kansai region, along with Kansai University, Kwansei Gakuin University, and Ritsumeikan University.$q$,$q$Description: Wikipedia, CC BY-SA 4.0$q$),
('d468cdba-e9bb-4398-9b9d-08070662b390'::uuid,$q$https://thumb.wikimedia.org/wikipedia/commons/thumb/c/c3/Ritsumeikan_University_logo_mark.svg/500px-Ritsumeikan_University_logo_mark.svg.png?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail$q$,$q$Photo: 秋山具義, Public domain, Wikimedia Commons$q$,$q$https://thumb.wikimedia.org/wikipedia/commons/thumb/9/9c/Zonshinkan_Hall_at_Ritsumeikan_Univ.jpg/1280px-Zonshinkan_Hall_at_Ritsumeikan_Univ.jpg?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail$q$,$q$Photo: AngloFrench91, CC BY-SA 4.0, Wikimedia Commons$q$,$q$Ritsumeikan University is a private university in Kyoto, Japan, that traces its origin to 1869. In addition to its main campus in Kyoto, the university also has satellite campuses in Ibaraki, Osaka and Kusatsu, Shiga. Today, Ritsumeikan University is known as one of Western Japan's most prestigious universities, part of the "Kan-Kan-Do-Rits" abbreviation that refers to the four leading private universities in the Keihanshin region.$q$,$q$Description: Wikipedia, CC BY-SA 4.0$q$),
('fea3705e-cb4b-41f1-beb5-6915ac2cf3a9'::uuid,null,null,$q$https://upload.wikimedia.org/wikipedia/commons/c/ce/Ritsumeikan_Asia_Pacific_University_-_01.jpg?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail_unscaled$q$,$q$Photo: JKT-c, CC BY 3.0, Wikimedia Commons$q$,$q$Ritsumeikan Asia Pacific University, commonly referred to as APU, is a private university in Beppu, Ōita, Japan. APU was established in 2000 through the collaboration of three parties from the public and private sectors: Ōita Prefecture, Beppu City, and the Ritsumeikan Trust. The university has a student body of about 5,850, including approximately 2,900 domestic, and 2,900 international students originating from 90 countries and regions.$q$,$q$Description: Wikipedia, CC BY-SA 4.0$q$),
('266f463e-18ae-4d41-b751-ead4f21d9420'::uuid,$q$https://thumb.wikimedia.org/wikipedia/commons/thumb/7/7c/Nucb.png/500px-Nucb.png?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail$q$,$q$Photo: Wahoowa83, Public domain, Wikimedia Commons$q$,null,null,$q$Nagoya University of Commerce & Business is a Japanese private university in Nisshin, Aichi, in the Tokai region of Japan.$q$,$q$Description: Wikipedia, CC BY-SA 4.0$q$),
('75064b8c-ff59-4bb5-a7f8-44d39edce99e'::uuid,$q$https://thumb.wikimedia.org/wikipedia/commons/thumb/4/4f/KUAS_logo_vector.svg/500px-KUAS_logo_vector.svg.png?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail$q$,$q$Photo: Kyoto University of Advanced Science, Public domain, Wikimedia Commons$q$,$q$https://thumb.wikimedia.org/wikipedia/commons/thumb/5/50/KGU_Photo02.jpg/1280px-KGU_Photo02.jpg?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail$q$,$q$Photo: Zfujio, CC BY-SA 3.0, Wikimedia Commons$q$,$q$Kyoto University of Advanced Science, formerly Kyoto Gakuen University, is a private university located in Ukyō-ku, Kyoto, Japan. Originally founded as a trade school in 1925 and established as university in 1969, KUAS was refounded in 2019 under the leadership of Shigenobu Nagamori. Its two campuses are located in Ukyō-ku, Kyoto City, and Kameoka City, Kyoto Prefecture.$q$,$q$Description: Wikipedia, CC BY-SA 4.0$q$),
('e037c643-d7d3-4809-8548-59b6528560df'::uuid,$q$https://thumb.wikimedia.org/wikipedia/commons/thumb/c/c5/Tokyo_International_University_Logo_in_Japanese.gif/500px-Tokyo_International_University_Logo_in_Japanese.gif?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail$q$,$q$Photo: Tokyo International University, Public domain, Wikimedia Commons$q$,$q$https://upload.wikimedia.org/wikipedia/commons/5/5a/Tokyo_International_University_campus1.jpg?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail_unscaled$q$,$q$Photo: TIU kouhou, CC BY-SA 3.0, Wikimedia Commons$q$,$q$Tokyo International University is a private, research-oriented liberal arts university which was founded in 1965. Its main campus is located in Toshima, Tokyo, where it moved from its original location in Kawagoe, Saitama Prefecture.$q$,$q$Description: Wikipedia, CC BY-SA 4.0$q$),
('5698c08f-54f5-4039-a939-0d1301f72a08'::uuid,null,null,$q$https://thumb.wikimedia.org/wikipedia/commons/thumb/f/f0/Shibaura_Institute_of_Technology.JPG/1280px-Shibaura_Institute_of_Technology.JPG?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail$q$,$q$Photo: Waka77, CC0, Wikimedia Commons$q$,$q$The Shibaura Institute of Technology, abbreviated as Shibaura kōdai, is a private university with the main campus located in Koto, Tokyo, Japan, with campuses located in Tokyo and Saitama.$q$,$q$Description: Wikipedia, CC BY-SA 4.0$q$),
('423d7b24-8978-4bf2-aad8-9695b4cdea18'::uuid,$q$https://upload.wikimedia.org/wikipedia/commons/b/b7/Temple-japan-logo.png?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail_unscaled$q$,$q$Photo: TUJCommunications, CC BY-SA 4.0, Wikimedia Commons$q$,$q$https://upload.wikimedia.org/wikipedia/commons/c/c9/TempleUJapan.jpg?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail_unscaled$q$,$q$Photo: Stevec240 at English Wikipedia, Public domain, Wikimedia Commons$q$,$q$Temple University, Japan Campus is an international campus of Temple University. TUJ is located in Setagaya-ku, Tokyo and Fushimi-ku, Kyoto, Japan. It is the oldest and largest foreign university in Japan, with 3,319 undergraduate students, of which approximately 23% are from Japan.$q$,$q$Description: Wikipedia, CC BY-SA 4.0$q$),
('abf630a3-3fdf-4c9f-8a38-d66471b4f25c'::uuid,$q$https://thumb.wikimedia.org/wikipedia/commons/thumb/0/0a/KAIST_logo.svg/500px-KAIST_logo.svg.png?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail$q$,$q$Photo: KAIST, Public domain, Wikimedia Commons$q$,$q$https://thumb.wikimedia.org/wikipedia/commons/thumb/7/7f/KAIST-Symbol-01.jpg/1280px-KAIST-Symbol-01.jpg?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail$q$,$q$Photo: Original uploader was Dr.aleks at en.wikipedia, CC BY 2.5, Wikimedia Commons$q$,$q$KAIST is a national research university located in Daedeok Innopolis, Daejeon, South Korea. KAIST was established by the Korean government in 1971 as the nation's first public, research-oriented science and engineering institution. KAIST has 10,504 full-time students and 1,342 faculty researchers and had a total budget of US$765 million in 2013, of which US$459 million was from research contracts.$q$,$q$Description: Wikipedia, CC BY-SA 4.0$q$),
('4aeaf998-aa54-4dd4-acd0-70c7f309aa19'::uuid,$q$https://upload.wikimedia.org/wikipedia/commons/9/9a/Unist_logo.png?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail_unscaled$q$,$q$Photo: Saldagacello, CC BY-SA 4.0, Wikimedia Commons$q$,null,null,$q$Ulsan National Institute of Science and Technology, is one of the four public universities in South Korea which are dedicated to research in science and technology, along with KAIST, GIST, and DGIST. UNIST was founded in 2007 in response to growing demand for higher education in the Korean industrial capital of Ulsan, where automotive, shipbuilding, petrochemical, and secondary cells industries are clustered. At the time of its foundation, UNIST was known for being the first national university in South Korea to be incorporated and thus administered by an independent board of trustees despite being funded by the central government.$q$,$q$Description: Wikipedia, CC BY-SA 4.0$q$),
('22511c15-c40e-4a75-be0b-7f4ce90da624'::uuid,$q$https://thumb.wikimedia.org/wikipedia/commons/thumb/6/6e/Yonsei_University_logotype%28ko%29.png/500px-Yonsei_University_logotype%28ko%29.png?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail$q$,$q$Photo: Yonsei University, Public domain, Wikimedia Commons$q$,$q$https://thumb.wikimedia.org/wikipedia/commons/thumb/7/75/Yeonsei_university_2011_%2816%29.JPG/1280px-Yeonsei_university_2011_%2816%29.JPG?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail$q$,$q$Photo: 콩가루, CC BY-SA 4.0, Wikimedia Commons$q$,$q$Yonsei University is a private Christian research university in Seoul, South Korea. Yonsei University is one of the three most prestigious universities in the country, part of a group referred to as SKY universities. Yonsei University traces its roots to the first modern medical center in Korea, Gwanghyewon (Korean: 광혜원; Hanja: 廣惠院; lit.$q$,$q$Description: Wikipedia, CC BY-SA 4.0$q$),
('28f977b8-aa7c-4162-9851-e06f2b16bb4c'::uuid,$q$https://thumb.wikimedia.org/wikipedia/commons/thumb/7/74/Korea_University_logotype_%28English_version%29.svg/500px-Korea_University_logotype_%28English_version%29.svg.png?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail$q$,$q$Photo: Korea University, Public domain, Wikimedia Commons$q$,null,null,$q$Korea University is a private research university in Seoul, South Korea. Korea University also maintains a satellite campus in Sejong City. Established in 1905 as Bosung College by Lee Yong-Ik, a prominent official of the Korean Empire, Korea University is among South Korea's oldest institutions of higher education, and is the nation's first modern private university.$q$,$q$Description: Wikipedia, CC BY-SA 4.0$q$),
('d20d7e96-21c7-47dc-8244-070bcf7b0744'::uuid,null,null,null,null,$q$The Gwangju Institute of Science and Technology is a public research university and institute of technology that was established in 1993 by a legislative act of the National Assembly of the Republic of Korea with its primary purpose to advance national science and technology through education, research, and international and industrial cooperation. Located in Gwangju, South Korea, GIST is recognized for its high research impact, consistently ranking among the top five globally in the "Citations per Faculty" category of the QS World University Rankings for nearly two decades. Following its 30th anniversary in 2023, the institute launched the "Vision 2053" initiative, which aims to position GIST as a top 50 global university by 2053 with a specialized focus on artificial intelligence and robotics.$q$,$q$Description: Wikipedia, CC BY-SA 4.0$q$),
('2fbe2df4-f1ac-467e-91a7-f14dbb578d83'::uuid,null,null,$q$https://upload.wikimedia.org/wikipedia/commons/4/48/%EC%9D%B4%ED%99%94%EC%97%AC%EC%9E%90%EB%8C%80%ED%95%99%EA%B5%90_%EB%8C%80%EA%B0%95%EB%8B%B9.jpg?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail_unscaled$q$,$q$Photo: Iamin22, CC BY-SA 4.0, Wikimedia Commons$q$,$q$Ewha Womans University is a private women's research university in Seoul, South Korea. It was originally founded as Ewha Haktang on May 31, 1886, by missionary Mary F. Scranton. Ewha Womans University has produced numerous South Korean women leaders, including politicians, CEOs, and legal professionals.$q$,$q$Description: Wikipedia, CC BY-SA 4.0$q$),
('421bcd98-650c-47b6-9c85-ee6102c8dd9f'::uuid,null,null,null,null,$q$SolBridge International School of Business is a private non profit AACSB accredited business school in Daejeon, South Korea, established by Woosong University in March 2007.$q$,$q$Description: Wikipedia, CC BY-SA 4.0$q$),
('3a3d8fcc-4149-4e97-8a5c-3e16f3257433'::uuid,$q$https://thumb.wikimedia.org/wikipedia/commons/thumb/2/2c/Stony_Brook_University_logo.svg/500px-Stony_Brook_University_logo.svg.png?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail$q$,$q$Photo: Unknown authorUnknown author, Public domain, Wikimedia Commons$q$,null,null,null,null),
('9212cdac-a243-4572-aee5-ae1f0dbf6a1c'::uuid,$q$https://thumb.wikimedia.org/wikipedia/commons/thumb/5/53/George_Mason_University_logo.svg/500px-George_Mason_University_logo.svg.png?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail$q$,$q$Photo: George Mason University, Public domain, Wikimedia Commons$q$,null,null,null,null),
('de82895a-2b40-45ba-92a6-0614658ae9ed'::uuid,$q$https://thumb.wikimedia.org/wikipedia/commons/thumb/3/30/University_of_Utah_horizontal_logo.svg/500px-University_of_Utah_horizontal_logo.svg.png?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail$q$,$q$Photo: University of Utah, Public domain, Wikimedia Commons$q$,null,null,null,null),
('7289023a-0d13-4f11-b0d8-505d700e8d2f'::uuid,null,null,$q$https://upload.wikimedia.org/wikipedia/commons/f/f2/Thu_gate.JPG?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail_unscaled$q$,$q$Photo: User:Yaoleilei, CC BY-SA 3.0, Wikimedia Commons$q$,$q$Tsinghua University is a public research university in Haidian, Beijing, China. It is affiliated with and funded by the Ministry of Education of China. The university is part of the Double First-Class Construction, and was a part of its predecessor initiatives: Project 211 and Project 985.$q$,$q$Description: Wikipedia, CC BY-SA 4.0$q$),
('238ee58b-6500-47d0-87a0-aed3092266f9'::uuid,null,null,$q$https://thumb.wikimedia.org/wikipedia/commons/thumb/5/5e/Hangzhou_Zhijiang_Daxue_20120518-25.jpg/1280px-Hangzhou_Zhijiang_Daxue_20120518-25.jpg?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail$q$,$q$Photo: Zhangzhugang, CC BY-SA 4.0, Wikimedia Commons$q$,$q$Zhejiang University is a public university in Hangzhou, Zhejiang, China. It is affiliated with the Ministry of Education. The university is part of Project 211, Project 985, and Double First-Class Construction.$q$,$q$Description: Wikipedia, CC BY-SA 4.0$q$),
('590a62d4-4928-47b7-8df9-c8be49530917'::uuid,$q$https://thumb.wikimedia.org/wikipedia/commons/thumb/4/44/Fudan_University_Logo.svg/500px-Fudan_University_Logo.svg.png?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail$q$,$q$Photo: Original: Fudan University Vector:  Prcmise, Public domain, Wikimedia Commons$q$,$q$https://upload.wikimedia.org/wikipedia/commons/d/d4/Fudan_university.jpg?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail_unscaled$q$,$q$Photo: Andrew Lih, CC BY-SA 3.0, Wikimedia Commons$q$,$q$Fudan University is a public university in Yangpu, Shanghai, China. It is affiliated with the Ministry of Education and is co-funded with the Shanghai Municipal Government. The university is part of Project 211, Project 985, and the Double First-Class Construction.$q$,$q$Description: Wikipedia, CC BY-SA 4.0$q$),
('c12d2a14-245a-4e92-af73-b59891bd7b34'::uuid,$q$https://upload.wikimedia.org/wikipedia/commons/4/48/SJTU_emblem_1940.jpg?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail_unscaled$q$,$q$Photo: Shanghai Jiao Tong University, Public domain, Wikimedia Commons$q$,$q$https://thumb.wikimedia.org/wikipedia/commons/thumb/8/89/Shanghai_Jiao_Tong_University_1.jpg/1280px-Shanghai_Jiao_Tong_University_1.jpg?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail$q$,$q$Photo: This illustration was made by Peter Potrowl. Please credit this with : © Peter P, CC BY 3.0, Wikimedia Commons$q$,$q$Shanghai Jiao Tong University is a public university in Shanghai, China. It is affiliated with the Ministry of Education of China. The university is part of Project 211, Project 985, and the Double First-Class Construction.$q$,$q$Description: Wikipedia, CC BY-SA 4.0$q$),
('9a1b561f-31c9-4398-974c-d3af7a324c01'::uuid,null,null,$q$https://thumb.wikimedia.org/wikipedia/commons/thumb/9/98/Tongjidaxue_Tushuguan.JPG/1280px-Tongjidaxue_Tushuguan.JPG?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail$q$,$q$Photo: Fayhoo, CC BY-SA 3.0, Wikimedia Commons$q$,$q$Tongji University is a public university located in Shanghai, China. It is affiliated with the Ministry of Education of China. The university is part of Project 211, Project 985, and the Double First-Class Construction.$q$,$q$Description: Wikipedia, CC BY-SA 4.0$q$),
('ad29ceb9-f69a-48b4-8bb3-5a5d0bbb8366'::uuid,null,null,$q$https://upload.wikimedia.org/wikipedia/commons/f/fc/Harbin_Institute_of_Technology_-_Main_Bldg.jpg?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail_unscaled$q$,$q$Photo: Yoshi Canopus, CC BY-SA 4.0, Wikimedia Commons$q$,$q$The Harbin Institute of Technology is a public science and engineering university in Nan'gang, Harbin, Heilongjiang, China. It is one of the top universities in China and is affiliated with the Ministry of Industry and Information Technology. The university is part of Project 211, Project 985, and the Double First-Class Construction.$q$,$q$Description: Wikipedia, CC BY-SA 4.0$q$),
('2780d873-8263-40b5-a458-6b404a79b5da'::uuid,null,null,$q$https://thumb.wikimedia.org/wikipedia/commons/thumb/9/9f/XJTU_Gate.jpg/1280px-XJTU_Gate.jpg?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail$q$,$q$Photo: Jucember, CC BY-SA 3.0, Wikimedia Commons$q$,$q$Xi'an Jiaotong University is a public university in Xi'an, Shaanxi, China. It is affiliated with and funded by the Ministry of Education of China. The university is part of Project 211, Project 985, and the Double First-Class Construction.$q$,$q$Description: Wikipedia, CC BY-SA 4.0$q$),
('a5576d7c-bb2b-484e-a66e-d94ba0941f9f'::uuid,$q$https://thumb.wikimedia.org/wikipedia/commons/thumb/7/75/Xiamen_University_logo.svg/500px-Xiamen_University_logo.svg.png?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail$q$,$q$Photo: 林文庆, Public domain, Wikimedia Commons$q$,$q$https://thumb.wikimedia.org/wikipedia/commons/thumb/b/b5/Panoramatic_view_of_xiamen_university_at_sunset.jpg/1280px-Panoramatic_view_of_xiamen_university_at_sunset.jpg?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail$q$,$q$Photo: Ratvirgin, CC BY-SA 3.0, Wikimedia Commons$q$,$q$Xiamen University is a public university in Siming, Xiamen, Fujian, China. It is affiliated with the Ministry of Education of China. The university is part of Project 211, Project 985, and the Double First-Class Construction.$q$,$q$Description: Wikipedia, CC BY-SA 4.0$q$),
('7504c985-9477-4c46-a353-80a2680c5afd'::uuid,null,null,$q$https://thumb.wikimedia.org/wikipedia/commons/thumb/b/b3/201704_Nanjing_Medical_University_Sir_Run_Run_Hospital.jpg/1280px-201704_Nanjing_Medical_University_Sir_Run_Run_Hospital.jpg?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail$q$,$q$Photo: MNXANL, CC BY-SA 4.0, Wikimedia Commons$q$,$q$Nanjing Medical University is a provincial public university in Nanjing, Jiangsu, China. It is affiliated with the Province of Jiangsu. The university is part of the Double First-Class Construction.$q$,$q$Description: Wikipedia, CC BY-SA 4.0$q$),
('2894b594-04f5-4a20-b31b-2103153f602b'::uuid,null,null,$q$https://thumb.wikimedia.org/wikipedia/commons/thumb/b/bc/Duke_Kunshan_Water_Feature.jpg/1280px-Duke_Kunshan_Water_Feature.jpg?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail$q$,$q$Photo: Crcolas, CC BY-SA 4.0, Wikimedia Commons$q$,$q$Duke Kunshan University is a Sino-foreign cooperative university in Kunshan, Jiangsu, China. It was established in 2013 by Duke University and Wuhan University. Upon graduation, undergraduate students receive degrees from both Duke University and Duke Kunshan University.$q$,$q$Description: Wikipedia, CC BY-SA 4.0$q$),
('f15b574e-69ea-49c4-b85e-5d7f87aa07ca'::uuid,null,null,$q$https://thumb.wikimedia.org/wikipedia/commons/thumb/c/ce/NYUSH_Lujiazui_Building.jpg/1280px-NYUSH_Lujiazui_Building.jpg?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail$q$,$q$Photo: JACK728, CC BY-SA 4.0, Wikimedia Commons$q$,$q$New York University Shanghai is a Sino-foreign cooperative university in Pudong, Shanghai, China. It was established in 2012 under a partnership between East China Normal University and New York University. It is the third degree-granting campus of New York University.$q$,$q$Description: Wikipedia, CC BY-SA 4.0$q$),
('72476341-12f0-4b36-ad47-1aafff965d68'::uuid,null,null,null,null,$q$The University of Nottingham Ningbo China is a Sino-foreign cooperative university in Ningbo, Zhejiang, China. It was established in 2004 by a partnership between the University of Nottingham and Zhejiang Wanli University. The university is recognized by the Ministry of Education of China as an independent legal entity.$q$,$q$Description: Wikipedia, CC BY-SA 4.0$q$),
('4af87a61-6fcd-4c94-8e13-6b552e73cea1'::uuid,null,null,$q$https://thumb.wikimedia.org/wikipedia/commons/thumb/a/a9/South_Campus_of_XJTLU.jpg/1280px-South_Campus_of_XJTLU.jpg?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail$q$,$q$Photo: SCJiang, CC BY-SA 4.0, Wikimedia Commons$q$,$q$Xi'an Jiaotong–Liverpool University is a Sino-foreign cooperative university in Suzhou, Jiangsu, China. It was established in 2006 through a partnership between Xi'an Jiaotong University and the University of Liverpool, and was approved by the Ministry of Education of the People's Republic of China. XJTLU is affiliated to both Xi'an Jiaotong University and the University of Liverpool.$q$,$q$Description: Wikipedia, CC BY-SA 4.0$q$),
('8461d6dc-2c70-41da-8dc4-ceef7365858e'::uuid,null,null,$q$https://thumb.wikimedia.org/wikipedia/commons/thumb/7/7a/PekingUniversityPic6.jpg/1280px-PekingUniversityPic6.jpg?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail$q$,$q$Photo: galaygobi, CC BY 2.0, Wikimedia Commons$q$,$q$Peking University is a public university in Haidian, Beijing, China. It is affiliated with and funded by the Ministry of Education. The university is part of Project 211, Project 985, and the Double First-Class Construction.$q$,$q$Description: Wikipedia, CC BY-SA 4.0$q$)
) v(id,logo_url,logo_credit,image_url,image_credit,description,description_credit)
where s.id = v.id;

update public.schools s set
  logo_url = coalesce(nullif(s.logo_url,''), v.logo_url),
  logo_credit = case when coalesce(s.logo_url,'')='' then v.logo_credit else s.logo_credit end,
  image_url = coalesce(nullif(s.image_url,''), v.image_url),
  image_credit = case when coalesce(s.image_url,'')='' then v.image_credit else s.image_credit end,
  description = coalesce(nullif(s.description,''), v.description),
  description_credit = case when coalesce(s.description,'')='' then v.description_credit else s.description_credit end
from (values
($q$California Institute of Technology$q$,$q$https://thumb.wikimedia.org/wikipedia/commons/thumb/7/75/Caltech_Logo.svg/500px-Caltech_Logo.svg.png?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail$q$,$q$Photo: California Institute of Technology, Public domain, Wikimedia Commons$q$,$q$https://thumb.wikimedia.org/wikipedia/commons/thumb/c/cc/Caltech_Entrance.jpg/1280px-Caltech_Entrance.jpg?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail$q$,$q$Photo: Canon.vs.nikon, CC BY-SA 3.0, Wikimedia Commons$q$,$q$The California Institute of Technology is a private research university in Pasadena, California, United States. The university is responsible for many modern scientific advancements and is among a small group of institutes of technology in the United States that are devoted to the instruction of pure and applied sciences. The institution was founded as a preparatory and vocational school by Amos G. Throop in 1891 and began attracting influential scientists such as George Ellery Hale, Arthur Amos Noyes, and Robert Andrews Millikan in the early 20th century.$q$,$q$Description: Wikipedia, CC BY-SA 4.0$q$),
($q$Claremont McKenna College$q$,$q$https://thumb.wikimedia.org/wikipedia/commons/thumb/9/96/Claremont_McKenna_College_wordmark.svg/500px-Claremont_McKenna_College_wordmark.svg.png?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail$q$,$q$Photo: Claremont McKenna College, Public domain, Wikimedia Commons$q$,$q$https://thumb.wikimedia.org/wikipedia/commons/thumb/a/a4/Claremont_Mckenna_College_campus.jpg/1280px-Claremont_Mckenna_College_campus.jpg?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail$q$,$q$Photo: Sdkb, CC BY-SA 4.0, Wikimedia Commons$q$,$q$Claremont McKenna College is a private liberal arts college in Claremont, California. CMC is one of the seven members of the Claremont Colleges consortium. Established in 1946 as a men's college, CMC was officially incorporated in 1947 and began admitting women in 1976.$q$,$q$Description: Wikipedia, CC BY-SA 4.0$q$),
($q$Harvey Mudd College$q$,$q$https://thumb.wikimedia.org/wikipedia/commons/thumb/9/95/Harvey_Mudd_College_logo.svg/500px-Harvey_Mudd_College_logo.svg.png?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail$q$,$q$Photo: Harvey Mudd College, Public domain, Wikimedia Commons$q$,$q$https://thumb.wikimedia.org/wikipedia/commons/thumb/b/b7/Hmc-dartmouth_entrance.jpg/1280px-Hmc-dartmouth_entrance.jpg?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail$q$,$q$Photo: The original uploader was Imagine at English Wikipedia., CC BY 2.5, Wikimedia Commons$q$,$q$Harvey Mudd College is a private liberal arts college in Claremont, California, focused on science and engineering. It is part of the Claremont Colleges, which share adjoining campus grounds and resources. The college enrolled 913 undergraduate students as of 2025 and awards the Bachelor of Science degree.$q$,$q$Description: Wikipedia, CC BY-SA 4.0$q$),
($q$Northeastern University Oakland$q$,$q$https://thumb.wikimedia.org/wikipedia/commons/thumb/0/02/Northeastern_Wordmark.svg/500px-Northeastern_Wordmark.svg.png?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail$q$,$q$Photo: Northeastern University, Public domain, Wikimedia Commons$q$,null,null,null,null),
($q$Pomona College$q$,$q$https://thumb.wikimedia.org/wikipedia/commons/thumb/b/bb/Pomona_College_logo.svg/500px-Pomona_College_logo.svg.png?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail$q$,$q$Photo: Pomona College, Public domain, Wikimedia Commons$q$,$q$https://upload.wikimedia.org/wikipedia/commons/3/35/Crookshank_Hall.jpg?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail_unscaled$q$,$q$Photo: Officialpomonacollege, CC BY-SA 3.0, Wikimedia Commons$q$,$q$Pomona College is a private college in Claremont, California, United States. It was established in 1887 by a group of Congregationalists who wanted to recreate a "college of the New England type" in Southern California. In 1925, it became the founding member of the Claremont Colleges consortium of adjacent, affiliated institutions.$q$,$q$Description: Wikipedia, CC BY-SA 4.0$q$),
($q$University of Southern California$q$,$q$https://thumb.wikimedia.org/wikipedia/commons/thumb/f/fe/University_of_Southern_California_logo.svg/500px-University_of_Southern_California_logo.svg.png?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail$q$,$q$Photo: Unknown authorUnknown author, Public domain, Wikimedia Commons$q$,$q$https://thumb.wikimedia.org/wikipedia/commons/thumb/3/3d/052607-016-BovardHall-USC.jpg/1280px-052607-016-BovardHall-USC.jpg?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail$q$,$q$Photo: Bobak Ha'Eri, CC BY 3.0, Wikimedia Commons$q$,$q$The University of Southern California is a private research university in Los Angeles, California, United States. Founded in 1880 by Robert M. Widney, it is the oldest private research university in California and has an enrollment of more than 45,000 students. The university is composed of a liberal arts school, the Dornsife College of Letters, Arts and Sciences, and 22 undergraduate, graduate, and professional schools, enrolling roughly 21,000 undergraduate and 25,000 post-graduate students from all fifty U.S. states and more than 115 countries.$q$,$q$Description: Wikipedia, CC BY-SA 4.0$q$),
($q$Colorado College$q$,$q$https://thumb.wikimedia.org/wikipedia/commons/thumb/3/34/Colorado_College_logo.svg/500px-Colorado_College_logo.svg.png?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail$q$,$q$Photo: Colorado College, Public domain, Wikimedia Commons$q$,$q$https://thumb.wikimedia.org/wikipedia/commons/thumb/1/1d/Cutler_Hall.JPG/1280px-Cutler_Hall.JPG?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail$q$,$q$Photo: Jeffrey Beall, CC BY-SA 3.0, Wikimedia Commons$q$,$q$Colorado College is a private liberal arts college in Colorado Springs, Colorado, United States. Founded in 1874 by Thomas Nelson Haskell in his daughter's memory, the college offers 42 majors and 54 minors, and enrolls approximately 2,000 undergraduates at its 90-acre campus. Colorado College is a member of the Associated Colleges of the Midwest, and is a QuestBridge partner.$q$,$q$Description: Wikipedia, CC BY-SA 4.0$q$),
($q$Wesleyan University$q$,$q$https://thumb.wikimedia.org/wikipedia/commons/thumb/e/e8/Wesleyan_University_logo.svg/500px-Wesleyan_University_logo.svg.png?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail$q$,$q$Photo: Unknown, Public domain, Wikimedia Commons$q$,$q$https://thumb.wikimedia.org/wikipedia/commons/thumb/1/10/College_row_at_wesleyan.jpg/1280px-College_row_at_wesleyan.jpg?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail$q$,$q$Photo: Smartalic34 (talk), CC BY-SA 3.0, Wikimedia Commons$q$,$q$Wesleyan University is a private liberal arts college in Middletown, Connecticut, United States. It was founded in 1831 as a men's college under the Methodist Episcopal Church and with the support of prominent residents of Middletown it became a secular, coeducational institution. Wesleyan is a primarily undergraduate institution with a small graduate program.$q$,$q$Description: Wikipedia, CC BY-SA 4.0$q$),
($q$Yale University$q$,$q$https://thumb.wikimedia.org/wikipedia/commons/thumb/0/07/Yale_University_Shield_1.svg/500px-Yale_University_Shield_1.svg.png?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail$q$,$q$Photo: Yale University, Public domain, Wikimedia Commons$q$,$q$https://upload.wikimedia.org/wikipedia/commons/f/fb/Yale_Law_School_in_the_Sterling_Law_Building.jpg?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail_unscaled$q$,$q$Photo: Pradipta Mitra, CC BY-SA 3.0, Wikimedia Commons$q$,$q$Yale University is a private Ivy League research university in New Haven, Connecticut, United States. Founded in 1701, Yale is the fourth oldest institution of higher education in the United States. It is one of the nine colonial colleges chartered before the American Revolution.$q$,$q$Description: Wikipedia, CC BY-SA 4.0$q$),
($q$Georgetown University$q$,$q$https://thumb.wikimedia.org/wikipedia/commons/thumb/9/99/Georgetown_University_Logotype.svg/500px-Georgetown_University_Logotype.svg.png?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail$q$,$q$Photo: Unknown authorUnknown author, Public domain, Wikimedia Commons$q$,$q$https://thumb.wikimedia.org/wikipedia/commons/thumb/c/c1/Healy_Hall_Georgetown_University.jpg/1280px-Healy_Hall_Georgetown_University.jpg?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail$q$,$q$Photo: APK, CC BY-SA 4.0, Wikimedia Commons$q$,$q$Georgetown University is a private Jesuit research university in Washington, D.C., United States. Founded by Bishop John Carroll in 1789, it is the oldest Catholic institution of higher education in the United States, the oldest university in Washington, D.C., and the nation's first federally chartered university. The university has eleven undergraduate and graduate schools.$q$,$q$Description: Wikipedia, CC BY-SA 4.0$q$),
($q$University of Miami$q$,$q$https://thumb.wikimedia.org/wikipedia/commons/thumb/0/0a/University_of_Miami_logo.svg/500px-University_of_Miami_logo.svg.png?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail$q$,$q$Photo: University of Miami, Public domain, Wikimedia Commons$q$,$q$https://thumb.wikimedia.org/wikipedia/commons/thumb/3/3e/University_of_Miami_Otto_G._Richter_Library.jpg/1280px-University_of_Miami_Otto_G._Richter_Library.jpg?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail$q$,$q$Public domain, Wikimedia Commons$q$,$q$The University of Miami is a private research university in Coral Gables, Florida, United States. As of 2025, the university enrolled 20,104 students in two colleges and eight schools across over 350 academic majors and programs, including the Miller School of Medicine in Miami's Health District, the law school on the main campus, the Rosenstiel School of Marine, Atmospheric, and Earth Science on Virginia Key, and additional research facilities in southern Miami-Dade County. The University of Miami offers 154 undergraduate, 150 master's, and 70 doctoral degree programs.$q$,$q$Description: Wikipedia, CC BY-SA 4.0$q$),
($q$Emory University$q$,null,null,$q$https://thumb.wikimedia.org/wikipedia/commons/thumb/4/4c/Candler_School_of_Theology.JPG/1280px-Candler_School_of_Theology.JPG?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail$q$,$q$Photo: Daniel Mayer, CC BY-SA 3.0, Wikimedia Commons$q$,$q$Emory University is a private research university in Atlanta, Georgia, United States. It was founded in 1836 as Emory College by the Methodist Episcopal Church and named in honor of Methodist bishop John Emory. Its main campus is in Druid Hills, four miles from downtown Atlanta.$q$,$q$Description: Wikipedia, CC BY-SA 4.0$q$),
($q$University of Chicago$q$,$q$https://thumb.wikimedia.org/wikipedia/commons/thumb/0/05/University_of_Chicago_wordmark.svg/500px-University_of_Chicago_wordmark.svg.png?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail$q$,$q$Photo: University of Chicago, Public domain, Wikimedia Commons$q$,$q$https://upload.wikimedia.org/wikipedia/commons/b/b4/Campus_Spring.jpg?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail_unscaled$q$,$q$Public domain, Wikimedia Commons$q$,$q$The University of Chicago is a private research university in the Hyde Park community area of Chicago, Illinois, United States. The university is composed of an undergraduate college and four graduate research divisions: the Arts & Humanities Division, the Biological Sciences Division, the Physical Sciences Division, and the Social Sciences Division, all of which include various organized departments and institutes. In addition, the university operates seven professional schools in the fields of business, social work, theology, public policy, law, medicine, and molecular engineering, along with a school of continuing studies.$q$,$q$Description: Wikipedia, CC BY-SA 4.0$q$),
($q$Northwestern University$q$,$q$https://upload.wikimedia.org/wikipedia/commons/4/48/Northwestern_University.png?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail_unscaled$q$,$q$Photo: Northwestern University, Public domain, Wikimedia Commons$q$,$q$https://upload.wikimedia.org/wikipedia/commons/a/a8/Northwestern_Arch.jpg?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail_unscaled$q$,$q$Photo: Rdsmith4, CC BY-SA 2.5, Wikimedia Commons$q$,$q$Northwestern University is a private research university in Evanston, Illinois, United States. Established in 1851, it is the oldest chartered university in Illinois. Northwestern was initially affiliated with the Methodist Episcopal Church but later became non-sectarian.$q$,$q$Description: Wikipedia, CC BY-SA 4.0$q$),
($q$University of Notre Dame$q$,null,null,$q$https://thumb.wikimedia.org/wikipedia/commons/thumb/a/a0/The_University_of_Notre_Dame_%22God_Quad%22.JPG/1280px-The_University_of_Notre_Dame_%22God_Quad%22.JPG?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail$q$,$q$Photo: Michael Fernandes, CC BY-SA 3.0, Wikimedia Commons$q$,$q$The University of Notre Dame du Lac is a private Catholic research university in Notre Dame, Indiana, United States. The university was founded in 1842 by members of the Congregation of Holy Cross, a Catholic religious order of priests and brothers. Its main campus covers 1,261 acres in a suburban setting and has landmarks such as the Golden Dome main building, Sacred Heart Basilica, the Grotto of Our Lady of Lourdes, the Word of Life mosaic mural, and Notre Dame Stadium.$q$,$q$Description: Wikipedia, CC BY-SA 4.0$q$),
($q$Grinnell College$q$,null,null,$q$https://thumb.wikimedia.org/wikipedia/commons/thumb/4/40/Grinnell_002.JPG/1280px-Grinnell_002.JPG?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail$q$,$q$Photo: Aureliusxv, Public domain, Wikimedia Commons$q$,$q$Grinnell College is a private liberal arts college in Grinnell, Iowa, United States. It was established as Iowa College in 1846 by a group of Congregationalists from New England. It has an "open curriculum," which means students need not follow a prescribed list of classes.$q$,$q$Description: Wikipedia, CC BY-SA 4.0$q$),
($q$Berea College$q$,$q$https://thumb.wikimedia.org/wikipedia/commons/thumb/2/20/Berea_college_full_logo.png/500px-Berea_college_full_logo.png?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail$q$,$q$Photo: Unknown authorUnknown author, Public domain, Wikimedia Commons$q$,$q$https://thumb.wikimedia.org/wikipedia/commons/thumb/a/a4/20140310_CampusShots_CAC_%284%29_%2813090607645%29.jpg/1280px-20140310_CampusShots_CAC_%284%29_%2813090607645%29.jpg?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail$q$,$q$Photo: IMCBerea College, CC BY 2.0, Wikimedia Commons$q$,$q$Berea College is a private liberal arts work college in Berea, Kentucky, United States. Founded in 1855, it was the first college in the Southern United States to be coeducational and racially integrated. It admitted non-White students from as early as 1866 until 1904, and again after 1954.$q$,$q$Description: Wikipedia, CC BY-SA 4.0$q$),
($q$Tulane University of Louisiana$q$,$q$https://thumb.wikimedia.org/wikipedia/commons/thumb/d/de/Tulane_University_full_logo.svg/500px-Tulane_University_full_logo.svg.png?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail$q$,$q$Photo: Unknown authorUnknown author, Public domain, Wikimedia Commons$q$,$q$https://thumb.wikimedia.org/wikipedia/commons/thumb/0/01/NewcombHallDownsideCenterJan08.jpg/1280px-NewcombHallDownsideCenterJan08.jpg?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail$q$,$q$Photo: Infrogmation of New Orleans, CC BY-SA 3.0, Wikimedia Commons$q$,$q$The Tulane University of Louisiana is a private research university in New Orleans, Louisiana, United States. Founded as the Medical College of Louisiana in 1834 by a cohort of medical doctors, it became a comprehensive public university as the University of Louisiana in 1847. The institution became private under the endowments of Paul Tulane and Josephine Louise Newcomb in 1884 and 1887.$q$,$q$Description: Wikipedia, CC BY-SA 4.0$q$),
($q$Bates College$q$,$q$https://thumb.wikimedia.org/wikipedia/commons/thumb/0/0e/Bates_College_wordmark.svg/500px-Bates_College_wordmark.svg.png?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail$q$,$q$Photo: Bates College, Public domain, Wikimedia Commons$q$,$q$https://upload.wikimedia.org/wikipedia/commons/1/18/Bates_College_Chapel.jpg?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail_unscaled$q$,$q$Photo: N.Y. Walton (Nywalton), Public domain, Wikimedia Commons$q$,$q$Bates College is a private liberal arts college in Lewiston, Maine, United States. Anchored by the Historic Quad, the campus of Bates totals 813 acres with a small urban campus. It maintains 600 acres of nature preserve known as the Bates–Morse Mountain Conservation Area near Campbell Island and a coastal center on Atkins Bay.$q$,$q$Description: Wikipedia, CC BY-SA 4.0$q$),
($q$Bowdoin College$q$,$q$https://upload.wikimedia.org/wikipedia/commons/0/09/Bowdoin_college_blacklogo.png?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail_unscaled$q$,$q$Photo: Unknown authorUnknown author, Public domain, Wikimedia Commons$q$,$q$https://upload.wikimedia.org/wikipedia/commons/c/cb/Hubbardhallb.jpg?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail_unscaled$q$,$q$Photo: Polarbear 11, CC BY 3.0, Wikimedia Commons$q$,$q$Bowdoin College is a private liberal arts college in Brunswick, Maine, United States. It was chartered in 1794. In addition to its Brunswick campus, Bowdoin owns a 118-acre coastal studies center on Orr's Island and a 200-acre scientific field station on Kent Island in the Bay of Fundy.$q$,$q$Description: Wikipedia, CC BY-SA 4.0$q$),
($q$Colby College$q$,$q$https://thumb.wikimedia.org/wikipedia/commons/thumb/1/10/Colby_College_logo.svg/500px-Colby_College_logo.svg.png?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail$q$,$q$Photo: Colby College, Public domain, Wikimedia Commons$q$,$q$https://upload.wikimedia.org/wikipedia/commons/d/da/Miller_Library%2C_Colby_College.jpg?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail_unscaled$q$,$q$Photo: Colby Mariam, CC BY-SA 4.0, Wikimedia Commons$q$,$q$Colby College is a private liberal arts college in Waterville, Maine, United States. Founded in 1813 as the Maine Literary and Theological Institution, it was renamed Waterville College in 1821. The donations of philanthropist Gardner Colby saw the institution renamed again to Colby University before settling on its current name, reflecting its liberal arts college curriculum, in 1899.$q$,$q$Description: Wikipedia, CC BY-SA 4.0$q$),
($q$Johns Hopkins University$q$,$q$https://thumb.wikimedia.org/wikipedia/commons/thumb/5/51/Johns_Hopkins_University_logo.png/500px-Johns_Hopkins_University_logo.png?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail$q$,$q$Photo: Johns Hopkins University, Public domain, Wikimedia Commons$q$,$q$https://thumb.wikimedia.org/wikipedia/commons/thumb/7/70/Johns_Hopkins%27_Historic_Dome_-_panoramio.jpg/1280px-Johns_Hopkins%27_Historic_Dome_-_panoramio.jpg?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail$q$,$q$Photo: Art Anderson, CC BY-SA 3.0, Wikimedia Commons$q$,$q$Johns Hopkins University, often abbreviated as Hopkins, is a private research university in Baltimore, Maryland, United States. Incorporated in 1867 and opened in 1876 based on the European research institution model, Johns Hopkins is considered to be the first research university in the U.S. The university was named for its first benefactor, the American businessman and Quaker philanthropist Johns Hopkins. Hopkins's $7 million bequest to establish the university and the affiliated Johns Hopkins Hospital in Baltimore was the largest philanthropic gift in U.S. history up to that time.$q$,$q$Description: Wikipedia, CC BY-SA 4.0$q$),
($q$Amherst College$q$,$q$https://upload.wikimedia.org/wikipedia/commons/7/7c/Amherst_College_logo.png?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail_unscaled$q$,$q$Photo: Amherst College, Public domain, Wikimedia Commons$q$,$q$https://thumb.wikimedia.org/wikipedia/commons/thumb/8/80/Frost_Library%2C_Amherst_College.jpg/1280px-Frost_Library%2C_Amherst_College.jpg?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail$q$,$q$Photo: Kenneth C. Zirkel, CC BY-SA 4.0, Wikimedia Commons$q$,$q$Amherst College is a private liberal arts college in Amherst, Massachusetts, United States. Founded in 1821 as an attempt to relocate Williams College by its then-president Zephaniah Swift Moore, Amherst is the third oldest institution of higher education in Massachusetts. The institution was named after the town, which in turn had been named after Jeffery, Lord Amherst, Commander-in-Chief of British forces of North America during the French and Indian War.$q$,$q$Description: Wikipedia, CC BY-SA 4.0$q$),
($q$Babson College$q$,null,null,$q$https://thumb.wikimedia.org/wikipedia/commons/thumb/f/fa/Tomasso_Hall%2C_Babson_College.jpg/1280px-Tomasso_Hall%2C_Babson_College.jpg?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail$q$,$q$Photo: Kenneth C. Zirkel, CC BY-SA 4.0, Wikimedia Commons$q$,$q$Babson College is a private business school in Wellesley, Massachusetts, United States specializing in entrepreneurship education. Founded in 1919 by Roger Babson, the college was established as the Babson Institute in his Wellesley home and initially granted one-year certificates. Babson College earned degree-granting authority from the Commonwealth of Massachusetts in 1947.$q$,$q$Description: Wikipedia, CC BY-SA 4.0$q$),
($q$Boston College$q$,$q$https://thumb.wikimedia.org/wikipedia/commons/thumb/2/21/Boston_College_Logotype.svg/500px-Boston_College_Logotype.svg.png?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail$q$,$q$Photo: Unknown authorUnknown author, Public domain, Wikimedia Commons$q$,$q$https://upload.wikimedia.org/wikipedia/commons/a/ae/Dustbowlsnow.jpg?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail_unscaled$q$,$q$CC BY-SA 3.0, Wikimedia Commons$q$,$q$Boston College is a private Catholic Jesuit research university in Chestnut Hill, Massachusetts, United States. Founded in 1863 by the Society of Jesus, a Catholic religious order, the university has more than 15,000 total students, making it the seventh largest Catholic university in the U.S. by enrollment. Boston College was originally located in the South End of Boston before moving most of its campus to Chestnut Hill in 1907.$q$,$q$Description: Wikipedia, CC BY-SA 4.0$q$),
($q$Boston University$q$,$q$https://thumb.wikimedia.org/wikipedia/commons/thumb/3/31/Boston_University_wordmark.svg/500px-Boston_University_wordmark.svg.png?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail$q$,$q$Photo: Boston University, Public domain, Wikimedia Commons$q$,$q$https://thumb.wikimedia.org/wikipedia/commons/thumb/2/2f/BU_College_of_Communication.jpg/1280px-BU_College_of_Communication.jpg?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail$q$,$q$Photo: Fletcher6, CC BY-SA 3.0, Wikimedia Commons$q$,$q$Boston University is a private research university in Boston, Massachusetts, United States. BU was founded in 1839 by a group of Boston Methodists with its original campus in Newbury, Vermont. It was chartered in Boston in 1869.$q$,$q$Description: Wikipedia, CC BY-SA 4.0$q$),
($q$Harvard University$q$,$q$https://thumb.wikimedia.org/wikipedia/commons/thumb/7/70/Harvard_University_logo.svg/500px-Harvard_University_logo.svg.png?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail$q$,$q$Photo: Pierre la Rose, Public domain, Wikimedia Commons$q$,$q$https://thumb.wikimedia.org/wikipedia/commons/thumb/1/11/Sanders_theater_2009y.JPG/1280px-Sanders_theater_2009y.JPG?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail$q$,$q$Photo: chensiyuan, CC BY-SA 4.0, Wikimedia Commons$q$,$q$Harvard University is a private Ivy League research university in Cambridge, Massachusetts, United States. Founded in 1636, and named Harvard College in 1639 in honor of its first benefactor, Puritan clergyman John Harvard, it is the oldest institution of higher learning in the United States. Its influence, wealth, and rankings have made it one of the most prestigious universities in the world.$q$,$q$Description: Wikipedia, CC BY-SA 4.0$q$),
($q$College of the Holy Cross$q$,null,null,$q$https://thumb.wikimedia.org/wikipedia/commons/thumb/6/61/Alumni_Hall%2C_College_of_the_Holy_Cross_%282006%29.jpg/1280px-Alumni_Hall%2C_College_of_the_Holy_Cross_%282006%29.jpg?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail$q$,$q$Photo: Paul Keleher, CC BY 2.0, Wikimedia Commons$q$,$q$The College of the Holy Cross is a private, Jesuit, liberal arts college in Worcester, Massachusetts, United States. Established in 1843 by Benedict Joseph Fenwick under the auspices of the Society of Jesus, Holy Cross was the first Catholic college in New England and is among the oldest Catholic institutions of higher education in the United States. Holy Cross is a residential, undergraduate college with approximately 3,000 students.$q$,$q$Description: Wikipedia, CC BY-SA 4.0$q$),
($q$Massachusetts Institute of Technology$q$,$q$https://thumb.wikimedia.org/wikipedia/commons/thumb/b/b8/MIT_2023_red_logo.svg/500px-MIT_2023_red_logo.svg.png?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail$q$,$q$Photo: Matthew Carter and others, owned by Massachusetts Institute of Technology, Public domain, Wikimedia Commons$q$,$q$https://thumb.wikimedia.org/wikipedia/commons/thumb/a/ac/MIT_Dome_night1_Edit.jpg/1280px-MIT_Dome_night1_Edit.jpg?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail$q$,$q$Photo: Fcb981, this edited version by Thermos, CC BY-SA 3.0, Wikimedia Commons$q$,$q$The Massachusetts Institute of Technology is a private research university in Cambridge, Massachusetts, United States. William Barton Rogers founded MIT to accelerate American industrialization through scientific knowledge. Initially funded by a federal land grant, the institute adopted a German polytechnic model emphasizing laboratory instruction in applied science and engineering, and moved from Boston's Back Bay to its current campus in Cambridge in 1916.$q$,$q$Description: Wikipedia, CC BY-SA 4.0$q$),
($q$Northeastern University$q$,$q$https://thumb.wikimedia.org/wikipedia/commons/thumb/0/02/Northeastern_Wordmark.svg/500px-Northeastern_Wordmark.svg.png?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail$q$,$q$Photo: Northeastern University, Public domain, Wikimedia Commons$q$,$q$https://thumb.wikimedia.org/wikipedia/commons/thumb/1/1d/Northeastern_University.jpg/1280px-Northeastern_University.jpg?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail$q$,$q$Photo: Edward Orde, CC BY-SA 4.0, Wikimedia Commons$q$,$q$Northeastern University is a private research university with its main campus in Boston, Massachusetts, United States. It was founded by the Boston Young Men's Christian Association in 1898 as an all-male institute before being incorporated as Northeastern College in 1916, gaining university status in 1922. With more than 38,000 students, Northeastern is the largest university in Massachusetts by enrollment.$q$,$q$Description: Wikipedia, CC BY-SA 4.0$q$),
($q$Tufts University$q$,$q$https://thumb.wikimedia.org/wikipedia/commons/thumb/1/12/Tufts_University_wordmark.svg/500px-Tufts_University_wordmark.svg.png?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail$q$,$q$Photo: Tufts University, Public domain, Wikimedia Commons$q$,$q$https://thumb.wikimedia.org/wikipedia/commons/thumb/1/1d/Tufts_Bendetson_hall.JPG/1280px-Tufts_Bendetson_hall.JPG?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail$q$,$q$Photo: HereToHelp, CC BY-SA 3.0, Wikimedia Commons$q$,$q$Tufts University is a private research university in Medford and Somerville, Massachusetts, United States, with additional facilities in Boston and Grafton, as well as Talloires, France. It was founded in 1852 as Tufts College by Christian universalists who sought to provide a nonsectarian institution of higher learning. For much of the 20th century, Jackson College for Women was the coordinate college of Tufts.$q$,$q$Description: Wikipedia, CC BY-SA 4.0$q$),
($q$Wellesley College$q$,$q$https://thumb.wikimedia.org/wikipedia/commons/thumb/3/3e/Formal_Logo_of_Wellesley_College%2C_Wellesley%2C_MA%2C_USA.svg/500px-Formal_Logo_of_Wellesley_College%2C_Wellesley%2C_MA%2C_USA.svg.png?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail$q$,$q$Photo: Wellesley College, Public domain, Wikimedia Commons$q$,$q$https://thumb.wikimedia.org/wikipedia/commons/thumb/e/e7/Green_Hall%2C_Wellesley_College%2C_Wellesley_MA.jpg/1280px-Green_Hall%2C_Wellesley_College%2C_Wellesley_MA.jpg?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail$q$,$q$Photo: John Phelan, CC BY-SA 3.0, Wikimedia Commons$q$,$q$Wellesley College is a private women's liberal arts college in Wellesley, Massachusetts, United States. Founded in 1870 by Henry and Pauline Durant as a female seminary, it is one of the Seven Sisters Colleges, an unofficial grouping of women's colleges in the northeastern United States. Wellesley enrolls approximately 2,500 students, including transgender, non-binary and genderqueer students since 2015.$q$,$q$Description: Wikipedia, CC BY-SA 4.0$q$),
($q$Williams College$q$,null,null,$q$https://thumb.wikimedia.org/wikipedia/commons/thumb/a/ae/Williams_College_-_Griffin_Hall.JPG/1280px-Williams_College_-_Griffin_Hall.JPG?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail$q$,$q$Photo: Daderot, Public domain, Wikimedia Commons$q$,$q$Williams College is a private liberal arts college in Williamstown, Massachusetts, United States. It was established as a men's college in 1793 with funds from the estate of Ephraim Williams, a colonist from the Province of Massachusetts Bay who was killed in the French and Indian War in 1755. Williams's main campus is located in Williamstown, in the Berkshires in rural northwestern Massachusetts, and contains more than 100 academic, athletic, and residential buildings.$q$,$q$Description: Wikipedia, CC BY-SA 4.0$q$),
($q$College of the Ozarks$q$,null,null,null,null,$q$College of the Ozarks is a private Christian college in Point Lookout, Missouri, United States. The college has an enrollment of 1,426 and over 30 academic majors in Bachelor of Arts and Bachelor of Science programs. The college charges no tuition for full-time students due to its student work program and donations.$q$,$q$Description: Wikipedia, CC BY-SA 4.0$q$),
($q$Dartmouth College$q$,$q$https://thumb.wikimedia.org/wikipedia/commons/thumb/f/f1/Dartmouth_College_logo.svg/500px-Dartmouth_College_logo.svg.png?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail$q$,$q$Photo: Dartmouth College, Public domain, Wikimedia Commons$q$,$q$https://thumb.wikimedia.org/wikipedia/commons/thumb/2/28/Dartmouth_College_campus_2007-06-23_Dartmouth_Hall_02.JPG/1280px-Dartmouth_College_campus_2007-06-23_Dartmouth_Hall_02.JPG?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail$q$,$q$Photo: Kane5187, Public domain, Wikimedia Commons$q$,$q$Dartmouth College is a private Ivy League research university in Hanover, New Hampshire, United States. Established in 1769 by Eleazar Wheelock and Samson Occom to train Native American Christian missionaries, Dartmouth is one of the nine colonial colleges chartered before the American Revolution. Following a liberal arts curriculum, Dartmouth provides undergraduate instruction in 40 academic departments and interdisciplinary programs, including 60 majors in the humanities, social sciences, natural sciences, and engineering.$q$,$q$Description: Wikipedia, CC BY-SA 4.0$q$),
($q$Princeton University$q$,$q$https://thumb.wikimedia.org/wikipedia/commons/thumb/4/42/Princeton_text_logo.svg/500px-Princeton_text_logo.svg.png?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail$q$,$q$Photo: Unknown authorUnknown author, Public domain, Wikimedia Commons$q$,$q$https://thumb.wikimedia.org/wikipedia/commons/thumb/d/d1/ClevelandTowerWatercolor20060829.jpg/1280px-ClevelandTowerWatercolor20060829.jpg?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail$q$,$q$Photo: Magneticcarpet, CC BY-SA 3.0, Wikimedia Commons$q$,$q$Princeton University is a private Ivy League research university in Princeton, New Jersey, United States. Founded in 1746 in Elizabeth as the College of New Jersey, Princeton is the fourth-oldest institution of higher education in the United States and one of the nine colonial colleges chartered before the American Revolution. The institution moved to Newark in 1747 and then to its Mercer County campus in Princeton nine years later.$q$,$q$Description: Wikipedia, CC BY-SA 4.0$q$),
($q$Barnard College$q$,$q$https://upload.wikimedia.org/wikipedia/commons/b/b7/Barnard_Logo.jpg?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail_unscaled$q$,$q$Photo: Barnard College, Public domain, Wikimedia Commons$q$,$q$https://upload.wikimedia.org/wikipedia/commons/f/f6/BarnardMilbank01.jpg?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail_unscaled$q$,$q$Photo: Shintashi, CC BY 3.0, Wikimedia Commons$q$,$q$Barnard College is a private women's liberal arts college in New York City, United States. It is affiliated with Columbia University and was founded in 1889 by a group of women led by young student activist Annie Nathan Meyer, who petitioned Columbia University's trustees to create an affiliated college named after university president Frederick A. P. Barnard. The college is one of the original Seven Sisters—seven liberal arts colleges in the Northeastern United States that were historically women's colleges.$q$,$q$Description: Wikipedia, CC BY-SA 4.0$q$),
($q$Colgate University$q$,$q$https://thumb.wikimedia.org/wikipedia/commons/thumb/2/2a/Colgate_University_wordmark.svg/500px-Colgate_University_wordmark.svg.png?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail$q$,$q$Photo: Colgate University, Public domain, Wikimedia Commons$q$,$q$https://thumb.wikimedia.org/wikipedia/commons/thumb/9/99/Colgate_University_Across_Taylor_Lake.jpg/1280px-Colgate_University_Across_Taylor_Lake.jpg?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail$q$,$q$Photo: Balon Greyjoy, CC0, Wikimedia Commons$q$,$q$Colgate University is a private liberal arts college in Hamilton, New York, United States. It was founded in 1819 as the Baptist Education Society of the State of New York and operated under that name until 1823, when it was renamed Hamilton Theological and Literary Institution, often called Hamilton College, then Madison College, and its present name since 1890. Colgate enrolls approximately 3,200 students in 56 undergraduate majors that culminate in a Bachelor of Arts degree.$q$,$q$Description: Wikipedia, CC BY-SA 4.0$q$),
($q$Columbia University in the City of New York$q$,$q$https://thumb.wikimedia.org/wikipedia/commons/thumb/3/33/Coat_of_Arms_of_Columbia_University.svg/500px-Coat_of_Arms_of_Columbia_University.svg.png?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail$q$,$q$Photo: Hstoops, CC0, Wikimedia Commons$q$,$q$https://thumb.wikimedia.org/wikipedia/commons/thumb/0/0e/Columbia_University_-_Low_Memorial_Library_%2848170370506%29.jpg/1280px-Columbia_University_-_Low_Memorial_Library_%2848170370506%29.jpg?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail$q$,$q$Photo: Ajay Suresh from New York, NY, USA, CC BY 2.0, Wikimedia Commons$q$,$q$Columbia University in the City of New York, commonly referred to as Columbia University, is a private Ivy League research university in New York City. Established in 1754 as King's College by royal charter under George II of Great Britain on the grounds of Trinity Church in Manhattan, it is the oldest institution of higher education in New York and the fifth-oldest in the United States. The university was renamed Columbia College in 1784 following the American Revolution, and in 1787 was placed under a private board of trustees headed by former students Alexander Hamilton and John Jay.$q$,$q$Description: Wikipedia, CC BY-SA 4.0$q$),
($q$Cornell University$q$,$q$https://thumb.wikimedia.org/wikipedia/commons/thumb/1/15/Cornell_University_Sign_20240525.jpg/500px-Cornell_University_Sign_20240525.jpg?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail$q$,$q$Photo: 颐园居, CC BY-SA 4.0, Wikimedia Commons$q$,$q$https://thumb.wikimedia.org/wikipedia/commons/thumb/3/34/Cornell_University%2C_Ho_Plaza_and_Sage_Hall.jpg/1280px-Cornell_University%2C_Ho_Plaza_and_Sage_Hall.jpg?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail$q$,$q$Photo: sach1tb, CC BY-SA 2.0, Wikimedia Commons$q$,$q$Cornell University is a private Ivy League research university based in Ithaca, New York, United States. The university was co-founded by American philanthropist Ezra Cornell and historian and educator Andrew Dickson White in 1865. Since its founding, Cornell University has been a co-educational and nonsectarian institution.$q$,$q$Description: Wikipedia, CC BY-SA 4.0$q$),
($q$Hamilton College$q$,$q$https://thumb.wikimedia.org/wikipedia/commons/thumb/3/35/Hamilton_College_logo.svg/500px-Hamilton_College_logo.svg.png?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail$q$,$q$Photo: Hamilton College, Public domain, Wikimedia Commons$q$,$q$https://thumb.wikimedia.org/wikipedia/commons/thumb/c/c4/Hamilton_College_theater.jpg/1280px-Hamilton_College_theater.jpg?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail$q$,$q$Photo: DanielPenfield, CC BY-SA 3.0, Wikimedia Commons$q$,$q$Hamilton College is a private liberal arts college in Clinton, New York, United States. It was established in 1812 in honor of Alexander Hamilton, one of its inaugural trustees, following a proposal made after his death in 1804. Since 1978, Hamilton has been a coeducational institution, having merged with its sister school, Kirkland College.$q$,$q$Description: Wikipedia, CC BY-SA 4.0$q$),
($q$New York University$q$,$q$https://thumb.wikimedia.org/wikipedia/commons/thumb/6/6a/Nyu_short_color.svg/500px-Nyu_short_color.svg.png?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail$q$,$q$Photo: New York University, Public domain, Wikimedia Commons$q$,$q$https://thumb.wikimedia.org/wikipedia/commons/thumb/7/7e/NYU07.JPG/1280px-NYU07.JPG?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail$q$,$q$Photo: Jonathan71, CC BY-SA 2.5, Wikimedia Commons$q$,$q$New York University is a private research university in New York City, United States. Chartered in 1831 by the New York State Legislature, NYU was founded in 1832 by Albert Gallatin as a non-sectarian all-male institution near City Hall based on a curriculum focused on a secular education. The university moved in 1833 and has maintained its main campus in Greenwich Village surrounding Washington Square Park.$q$,$q$Description: Wikipedia, CC BY-SA 4.0$q$),
($q$Vassar College$q$,$q$https://thumb.wikimedia.org/wikipedia/commons/thumb/9/9d/Vassar_college_garnet_logo.svg/500px-Vassar_college_garnet_logo.svg.png?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail$q$,$q$Photo: Unknown authorUnknown author, Public domain, Wikimedia Commons$q$,$q$https://thumb.wikimedia.org/wikipedia/commons/thumb/6/63/New_England_Building%2C_November_2014.jpg/1280px-New_England_Building%2C_November_2014.jpg?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail$q$,$q$Photo: Collin Knopp-Schwyn, CC BY 4.0, Wikimedia Commons$q$,$q$Vassar College is a private liberal arts college in the town of Poughkeepsie, New York, United States. Founded in 1861 by Matthew Vassar, it was the second degree-granting institution of higher education for women in the United States. The college became coeducational in 1969.$q$,$q$Description: Wikipedia, CC BY-SA 4.0$q$),
($q$Webb Institute$q$,$q$https://upload.wikimedia.org/wikipedia/commons/7/78/WebbInstitutelogo.png?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail_unscaled$q$,$q$Photo: Webb Institute, CC BY-SA 3.0, Wikimedia Commons$q$,null,null,$q$Webb Institute is a private college specialized in engineering and located in Glen Cove, New York, United States. Each graduate of Webb Institute earns a Bachelor of Science degree in naval architecture and marine engineering. The school is noted in the marine industry for its emphasis on ship design and systems engineering, its practical work experience, and its free tuition for domestic students.$q$,$q$Description: Wikipedia, CC BY-SA 4.0$q$),
($q$Davidson College$q$,$q$https://thumb.wikimedia.org/wikipedia/commons/thumb/d/da/Davidson_College_logo.png/500px-Davidson_College_logo.png?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail$q$,$q$Photo: Davidson College, Public domain, Wikimedia Commons$q$,$q$https://thumb.wikimedia.org/wikipedia/commons/thumb/a/ab/Chambers_Building%2C_Davidson_College_%28Davidson%2C_North_Carolina%29.jpg/1280px-Chambers_Building%2C_Davidson_College_%28Davidson%2C_North_Carolina%29.jpg?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail$q$,$q$Photo: Dacoslett at English Wikipedia, Public domain, Wikimedia Commons$q$,$q$Davidson College is a private liberal arts college in Davidson, North Carolina, United States. It was established in 1837 by the Concord Presbytery and named after Revolutionary War general William Lee Davidson, who was killed at the nearby Battle of Cowan's Ford. Davidson is a four-year undergraduate institution and enrolls 1,973 students from 50 states and territories, Washington, D.C., and 46 countries.$q$,$q$Description: Wikipedia, CC BY-SA 4.0$q$),
($q$Duke University$q$,$q$https://thumb.wikimedia.org/wikipedia/commons/thumb/e/e6/Duke_University_logo.svg/500px-Duke_University_logo.svg.png?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail$q$,$q$Photo: Duke University, Shep, Public domain, Wikimedia Commons$q$,$q$https://thumb.wikimedia.org/wikipedia/commons/thumb/a/af/Duke_Chapel_4_16_05.jpg/1280px-Duke_Chapel_4_16_05.jpg?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail$q$,$q$Public domain, Wikimedia Commons$q$,$q$Duke University is a private research university in Durham, North Carolina, United States. Founded by Methodists and Quakers in the present-day city of Trinity in 1838, the school moved to Durham in 1892. In 1924, tobacco and electric power industrialist James Buchanan Duke established the Duke Endowment and the institution changed its name to honor his deceased father, Washington Duke.$q$,$q$Description: Wikipedia, CC BY-SA 4.0$q$),
($q$Denison University$q$,$q$https://thumb.wikimedia.org/wikipedia/commons/thumb/c/cb/Denison_University_logo.svg/500px-Denison_University_logo.svg.png?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail$q$,$q$Photo: Denison University, Public domain, Wikimedia Commons$q$,$q$https://thumb.wikimedia.org/wikipedia/commons/thumb/b/b6/SwaseyObservatoryChapelDenisonUniversity.jpg/1280px-SwaseyObservatoryChapelDenisonUniversity.jpg?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail$q$,$q$Photo: Pbass1956, CC BY-SA 3.0, Wikimedia Commons$q$,$q$Denison University is a private liberal arts college in Granville, Ohio, United States. One of the earliest colleges established in the former Northwest Territory, Denison University was founded in 1831. It was first called the Granville Literary and Theological Institution, later took the name Granville College, and, in the mid-1850s, was renamed Denison University, in honor of William S. Denison, a major early benefactor.$q$,$q$Description: Wikipedia, CC BY-SA 4.0$q$),
($q$Carnegie Mellon University$q$,$q$https://thumb.wikimedia.org/wikipedia/commons/thumb/f/f3/Carnegie_Mellon_University_wordmark.svg/500px-Carnegie_Mellon_University_wordmark.svg.png?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail$q$,$q$Photo: Carnegie Mellon University, Public domain, Wikimedia Commons$q$,$q$https://upload.wikimedia.org/wikipedia/commons/8/85/CMU_campus_Cathedral_Learning_background.jpg?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail_unscaled$q$,$q$CC BY-SA 2.0, Wikimedia Commons$q$,$q$Carnegie Mellon University is a private research university in Pittsburgh, Pennsylvania, United States. The institution was established in 1900 by Andrew Carnegie as the Carnegie Technical Schools. In 1912, it became the Carnegie Institute of Technology and began granting four-year degrees.$q$,$q$Description: Wikipedia, CC BY-SA 4.0$q$),
($q$Haverford College$q$,$q$https://thumb.wikimedia.org/wikipedia/commons/thumb/9/9d/Haverford_college_wordmark.png/500px-Haverford_college_wordmark.png?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail$q$,$q$Photo: Unknown authorUnknown author, Public domain, Wikimedia Commons$q$,$q$https://thumb.wikimedia.org/wikipedia/commons/thumb/7/7a/Haverfordfounders.jpg/1280px-Haverfordfounders.jpg?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail$q$,$q$Photo: Jackbauerinvc (talk), CC BY-SA 3.0, Wikimedia Commons$q$,$q$Haverford College is a private liberal arts college in Haverford, Pennsylvania, United States. It was founded as a men's college in 1833 by members of the Religious Society of Friends. Haverford began accepting non-Quakers in 1849 and women in 1980.$q$,$q$Description: Wikipedia, CC BY-SA 4.0$q$),
($q$University of Pennsylvania$q$,$q$https://thumb.wikimedia.org/wikipedia/commons/thumb/7/7c/Shield_of_the_University_of_Pennsylvania.svg/500px-Shield_of_the_University_of_Pennsylvania.svg.png?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail$q$,$q$Photo: Unknown authorUnknown author, Public domain, Wikimedia Commons$q$,$q$https://thumb.wikimedia.org/wikipedia/commons/thumb/d/df/College_Hall%2C_University_of_Pennsylvania.jpg/1280px-College_Hall%2C_University_of_Pennsylvania.jpg?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail$q$,$q$Photo: Michel Alexandre Salim, CC BY-SA 2.0, Wikimedia Commons$q$,$q$The University of Pennsylvania is a private Ivy League research university in Philadelphia, Pennsylvania, United States. Chartered in 1755 by its first president Benjamin Franklin, who advocated for an educational institution that trained leaders in academia, commerce, and public service, it is one of nine colonial colleges in the country. The university has 4 undergraduate schools and 12 graduate and professional schools.$q$,$q$Description: Wikipedia, CC BY-SA 4.0$q$),
($q$Swarthmore College$q$,$q$https://thumb.wikimedia.org/wikipedia/commons/thumb/e/e5/Swarthmore_college_simplelogo.png/500px-Swarthmore_college_simplelogo.png?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail$q$,$q$Photo: Unknown authorUnknown author, Public domain, Wikimedia Commons$q$,$q$https://thumb.wikimedia.org/wikipedia/commons/thumb/2/26/Parrish_Hall.jpg/1280px-Parrish_Hall.jpg?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail$q$,$q$Photo: Ugen64 at English Wikipedia, Public domain, Wikimedia Commons$q$,$q$Swarthmore College is a private liberal arts college in Swarthmore, Pennsylvania, United States. Founded in 1864, with its first classes held in 1869, Swarthmore is one of the earliest coeducational colleges in the United States. It was established as a college under the Religious Society of Friends.$q$,$q$Description: Wikipedia, CC BY-SA 4.0$q$),
($q$Brown University$q$,$q$https://thumb.wikimedia.org/wikipedia/commons/thumb/a/a1/Brown_University_logo.svg/500px-Brown_University_logo.svg.png?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail$q$,$q$Photo: Brown University, Public domain, Wikimedia Commons$q$,$q$https://thumb.wikimedia.org/wikipedia/commons/thumb/6/6c/Manning_Chapel.jpg/1280px-Manning_Chapel.jpg?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail$q$,$q$Photo: No machine-readable author provided. Dale182 assumed (based on copyright claims), CC BY-SA 3.0, Wikimedia Commons$q$,$q$Brown University is a private Ivy League research university in Providence, Rhode Island, United States. The university is the seventh-oldest institution of higher education in the United States, founded in 1764 as the College in the English Colony of Rhode Island and Providence Plantations. One of nine colonial colleges chartered before the American Revolution, it was the first American college to codify that admission and instruction of students was to be equal regardless of the religious affiliation of students.$q$,$q$Description: Wikipedia, CC BY-SA 4.0$q$),
($q$Rhode Island School of Design$q$,$q$https://thumb.wikimedia.org/wikipedia/commons/thumb/5/57/RISD_short_wordmark.svg/500px-RISD_short_wordmark.svg.png?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail$q$,$q$Photo: Jordan Gushwa, Public domain, Wikimedia Commons$q$,$q$https://thumb.wikimedia.org/wikipedia/commons/thumb/8/8f/Museum_of_Art%2C_RISD%2C_Providence_RI.jpg/1280px-Museum_of_Art%2C_RISD%2C_Providence_RI.jpg?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail$q$,$q$Photo: John Phelan, CC BY-SA 3.0, Wikimedia Commons$q$,$q$The Rhode Island School of Design is a private art school in Providence, Rhode Island, United States. The school was founded as a coeducational institution in 1877 by Helen Adelia Rowe Metcalf, who sought to increase the accessibility of design education to women. Today, RISD offers bachelor's and master's degree programs across 19 majors and enrolls approximately 2,000 undergraduate and 500 graduate students.$q$,$q$Description: Wikipedia, CC BY-SA 4.0$q$),
($q$Vanderbilt University$q$,$q$https://thumb.wikimedia.org/wikipedia/commons/thumb/d/d0/Vanderbilt_University_logo.svg/500px-Vanderbilt_University_logo.svg.png?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail$q$,$q$Photo: Vanderbilt University, Public domain, Wikimedia Commons$q$,$q$https://thumb.wikimedia.org/wikipedia/commons/thumb/7/7e/Vanderbilt_university_campus_2017.jpg/1280px-Vanderbilt_university_campus_2017.jpg?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail$q$,$q$Photo: Stablenode, CC BY-SA 4.0, Wikimedia Commons$q$,$q$Vanderbilt University is a private research university in Nashville, Tennessee, United States. Founded in 1873, it was named in honor of shipping and railroad magnate Cornelius Vanderbilt, who provided the school with its initial $1 million endowment in the hopes that his gift, and the greater work of the university, would help to heal the sectional wounds inflicted by the American Civil War. Vanderbilt is a founding member of the Southeastern Conference and has been the conference's only private school since 1966.$q$,$q$Description: Wikipedia, CC BY-SA 4.0$q$),
($q$Rice University$q$,$q$https://upload.wikimedia.org/wikipedia/commons/3/34/Rice_University_Logo.png?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail_unscaled$q$,$q$Photo: Thiago602, CC BY-SA 4.0, Wikimedia Commons$q$,$q$https://thumb.wikimedia.org/wikipedia/commons/thumb/a/a1/Rice_University_-_Sally_Port.JPG/1280px-Rice_University_-_Sally_Port.JPG?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail$q$,$q$Photo: Daderot, Public domain, Wikimedia Commons$q$,$q$William Marsh Rice University, also known as Rice University, is a private research university in Houston, Texas, United States. Established in 1912, it spans 300 acres. The university consists of eight constituent schools in the fields of architecture, business, continuing studies, engineering, humanities, music, natural sciences, and social sciences.$q$,$q$Description: Wikipedia, CC BY-SA 4.0$q$),
($q$Middlebury College$q$,$q$https://upload.wikimedia.org/wikipedia/commons/d/dd/MiddleburySeal220.gif?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail_unscaled$q$,$q$Photo: Middlebury College, Public domain, Wikimedia Commons$q$,$q$https://thumb.wikimedia.org/wikipedia/commons/thumb/1/1b/McCardellBicentennialHall.jpg/1280px-McCardellBicentennialHall.jpg?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail$q$,$q$Photo: PenelopeIsMe, CC BY-SA 3.0, Wikimedia Commons$q$,$q$Middlebury College is a private liberal arts college in Middlebury, Vermont, United States. Founded in 1800 by Congregationalists, Middlebury was the first operating college or university in Vermont. In the fall of 2024, the college enrolled 2,760 undergraduates from all 50 states and 74 countries and offers 45 majors in the arts and humanities as well as joint engineering programs.$q$,$q$Description: Wikipedia, CC BY-SA 4.0$q$),
($q$Washington and Lee University$q$,$q$https://thumb.wikimedia.org/wikipedia/commons/thumb/1/12/Web_wordmark1.png/500px-Web_wordmark1.png?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail$q$,$q$Photo: Washington and Lee University, Public domain, Wikimedia Commons$q$,$q$https://thumb.wikimedia.org/wikipedia/commons/thumb/d/db/2008-0831-WashingtonandLeeUniversity.jpg/1280px-2008-0831-WashingtonandLeeUniversity.jpg?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail$q$,$q$Photo: Bobak Ha'Eri, CC BY 3.0, Wikimedia Commons$q$,$q$Washington and Lee University is a private liberal arts college in Lexington, Virginia, United States. Established in 1749 as Augusta Academy, it is among the oldest institutions of higher learning in the US. Washington and Lee's 325-acre campus sits at the edge of Lexington and abuts the campus of the Virginia Military Institute in the Shenandoah Valley region between the Blue Ridge Mountains and the Allegheny Mountains. The institution consists of three academic units: the college itself; the Williams School of Commerce, Economics, and Politics; and the School of Law.$q$,$q$Description: Wikipedia, CC BY-SA 4.0$q$),
($q$Stanford University$q$,$q$https://thumb.wikimedia.org/wikipedia/commons/thumb/a/a9/Stanford_wordmark_%282012%29.svg/500px-Stanford_wordmark_%282012%29.svg.png?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail$q$,$q$Photo: Unknown authorUnknown author, Public domain, Wikimedia Commons$q$,$q$https://thumb.wikimedia.org/wikipedia/commons/thumb/c/cd/Stanford_Oval_May_2011_panorama.jpg/1280px-Stanford_Oval_May_2011_panorama.jpg?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail$q$,$q$Photo: King of Hearts, CC BY-SA 3.0, Wikimedia Commons$q$,$q$Leland Stanford Junior University, commonly referred to as Stanford University, is a private research university in Stanford, California, United States. It was founded in 1885 by railroad magnate Leland Stanford and his wife, Jane, in memory of their only child, Leland Stanford Jr., who died from typhoid at the age of 15. The university admitted its first students in 1891, opening as a coeducational and non-denominational institution.$q$,$q$Description: Wikipedia, CC BY-SA 4.0$q$)
) v(name,logo_url,logo_credit,image_url,image_credit,description,description_credit)
where s.name = v.name and s.country = 'United States' and s.type = 'Private';
commit;

-- Check
select country, count(*) schools, count(nullif(logo_url,'')) with_logo, count(nullif(image_url,'')) with_photo, count(nullif(description,'')) with_text
from public.schools where (country in ('Japan','South Korea','China')) or (country='United States' and type='Private') group by country order by country;
